#![cfg(sidereon_repo_tests)]
//! Bit-exact (0 ULP) determinism lock for the Orekit 13.1.10 / Hipparchus 4.0.3
//! shadow fraction, forward-mode gradient, and cannonball SRP port.
//!
//! Fixture: `tests/fixtures/eclipse/orekit_shadow_srp_oracle.json`, generated by
//! `fixtures-generators/orekit_shadow_srp_oracle/generate.sh`.

use nalgebra::Vector3;
use serde::Deserialize;
use sidereon_core::astro::constants::{
    astro::{AU_KM, IAU_2015_SOLAR_RADIUS_KM, MOON_RADIUS_KM},
    earth::MEAN_EARTH_RADIUS_KM,
    units::M_PER_KM,
};
use sidereon_core::astro::events::eclipse::{
    moon_shadow_fraction, shadow_fraction_with_model_and_moon,
    shadow_fraction_with_model_moon_and_gradient, EarthShadowModel, WGS84_FLATTENING,
};
use sidereon_core::astro::forces::SolarRadiationPressure;

const FIXTURE_JSON: &str = include_str!("fixtures/eclipse/orekit_shadow_srp_oracle.json");

#[derive(Debug, Deserialize)]
struct Source {
    orekit: String,
    hipparchus: String,
}

#[derive(Debug, Deserialize)]
struct EarthCase {
    name: String,
    earth_flattening: f64,
    sat_km_bits: [String; 3],
    sun_km_bits: [String; 3],
    clear_moon_km_bits: [String; 3],
    clear_moon_lighting_double_bits: String,
    clear_moon_accel_double_bits: [String; 3],
    clear_moon_lighting_field_val_bits: String,
    clear_moon_lighting_field_grad_bits: [String; 3],
}

#[derive(Debug, Deserialize)]
struct MoonCase {
    name: String,
    sat_km_bits: [String; 3],
    sun_km_bits: [String; 3],
    moon_km_bits: [String; 3],
    lighting_double_bits: String,
}

#[derive(Debug, Deserialize)]
struct EarthMoonCase {
    name: String,
    earth_flattening: f64,
    sat_km_bits: [String; 3],
    sun_km_bits: [String; 3],
    moon_km_bits: [String; 3],
    orekit_subtracts_mutual: bool,
    orekit_lighting_double_bits: String,
    orekit_accel_double_bits: [String; 3],
    orekit_lighting_field_val_bits: String,
    orekit_lighting_field_grad_bits: [String; 3],
    union_lighting_double_bits: String,
    union_accel_double_bits: [String; 3],
    union_lighting_field_val_bits: String,
    union_lighting_field_grad_bits: [String; 3],
}

#[derive(Debug, Deserialize)]
struct OracleFixture {
    _source: Source,
    sun_radius_m_bits: String,
    earth_radius_m_bits: String,
    moon_radius_m_bits: String,
    wgs84_flattening_bits: String,
    d_ref_km_bits: String,
    p_ref_n_m2_bits: String,
    cr_bits: String,
    area_to_mass_m2_kg_bits: String,
    earth_cases: Vec<EarthCase>,
    moon_cases: Vec<MoonCase>,
    earth_moon_cases: Vec<EarthMoonCase>,
}

fn parse_bits(s: &str) -> u64 {
    let hex = s.strip_prefix("0x").expect("hex prefix");
    u64::from_str_radix(hex, 16).expect("valid hex")
}

fn parse_f64(s: &str) -> f64 {
    f64::from_bits(parse_bits(s))
}

fn parse_vec3(v: &[String; 3]) -> [f64; 3] {
    [parse_f64(&v[0]), parse_f64(&v[1]), parse_f64(&v[2])]
}

fn earth_model(flattening: f64) -> EarthShadowModel {
    if flattening == 0.0 {
        EarthShadowModel::Spherical
    } else {
        EarthShadowModel::Wgs84Oblate
    }
}

fn assert_bits_eq(label: &str, got: f64, expected: f64) {
    assert_eq!(
        got.to_bits(),
        expected.to_bits(),
        "{label}: got {got:.17e} (0x{:016x}) != expected {expected:.17e} (0x{:016x}), diff = {:.3e}",
        got.to_bits(),
        expected.to_bits(),
        got - expected
    );
}

#[test]
fn public_eclipse_and_srp_apis_match_orekit_bit_for_bit() {
    let fixture: OracleFixture =
        serde_json::from_str(FIXTURE_JSON).expect("parse Orekit shadow/SRP oracle fixture");
    assert_eq!(fixture._source.orekit, "13.1.10");
    assert_eq!(fixture._source.hipparchus, "4.0.3");
    assert_eq!(
        (IAU_2015_SOLAR_RADIUS_KM * M_PER_KM).to_bits(),
        parse_bits(&fixture.sun_radius_m_bits)
    );
    assert_eq!(
        (MEAN_EARTH_RADIUS_KM * M_PER_KM).to_bits(),
        parse_bits(&fixture.earth_radius_m_bits)
    );
    assert_eq!(
        (MOON_RADIUS_KM * M_PER_KM).to_bits(),
        parse_bits(&fixture.moon_radius_m_bits)
    );
    assert_eq!(
        WGS84_FLATTENING.to_bits(),
        parse_bits(&fixture.wgs84_flattening_bits)
    );
    assert_eq!(AU_KM.to_bits(), parse_bits(&fixture.d_ref_km_bits));

    let base_srp = SolarRadiationPressure::with_pressure(
        parse_f64(&fixture.cr_bits),
        parse_f64(&fixture.area_to_mass_m2_kg_bits),
        parse_f64(&fixture.p_ref_n_m2_bits),
        parse_f64(&fixture.d_ref_km_bits),
    )
    .expect("valid SRP")
    .with_moon_eclipse(true);

    // 1. Earth alone with a clear Moon perpendicular to the Sun direction
    //    (d_moon < d_sun, so no departure fires), verifying every earth_case
    //    through the public two-body APIs against raw Orekit (n = 2) at 0 ULP.
    for case in &fixture.earth_cases {
        let sat = parse_vec3(&case.sat_km_bits);
        let sun = parse_vec3(&case.sun_km_bits);
        let clear_moon = parse_vec3(&case.clear_moon_km_bits);
        let model = earth_model(case.earth_flattening);

        let shadow = shadow_fraction_with_model_and_moon(sat, sun, clear_moon, model)
            .unwrap_or_else(|e| panic!("earth {}: {e:?}", case.name));
        let expected_shadow = 1.0 - parse_f64(&case.clear_moon_lighting_double_bits);
        assert_bits_eq(
            &format!("earth {} shadow", case.name),
            shadow,
            expected_shadow,
        );

        let (field_shadow, field_grad) =
            shadow_fraction_with_model_moon_and_gradient(sat, sun, clear_moon, model)
                .unwrap_or_else(|e| panic!("earth {} grad: {e:?}", case.name));
        let expected_field_shadow = 1.0 - parse_f64(&case.clear_moon_lighting_field_val_bits);
        assert_bits_eq(
            &format!("earth {} field shadow", case.name),
            field_shadow,
            expected_field_shadow,
        );
        for axis in 0..3 {
            let expected_g = -parse_f64(&case.clear_moon_lighting_field_grad_bits[axis]) * M_PER_KM;
            assert_bits_eq(
                &format!("earth {} grad[{axis}]", case.name),
                field_grad[axis],
                expected_g,
            );
        }

        let srp = base_srp.with_earth_shadow_model(model);
        let accel = srp
            .acceleration_with_sun_moon(
                Vector3::from(sat),
                Vector3::from(sun),
                Vector3::from(clear_moon),
            )
            .unwrap_or_else(|e| panic!("earth {} accel: {e:?}", case.name));
        for axis in 0..3 {
            let expected_a = parse_f64(&case.clear_moon_accel_double_bits[axis]) / M_PER_KM;
            assert_bits_eq(
                &format!("earth {} accel[{axis}]", case.name),
                accel[axis],
                expected_a,
            );
        }
    }

    // 2. Moon alone via moon_shadow_fraction.
    for case in &fixture.moon_cases {
        let sat = parse_vec3(&case.sat_km_bits);
        let sun = parse_vec3(&case.sun_km_bits);
        let moon = parse_vec3(&case.moon_km_bits);
        let shadow = moon_shadow_fraction(sat, sun, moon)
            .unwrap_or_else(|e| panic!("moon {}: {e:?}", case.name));
        let expected_shadow = 1.0 - parse_f64(&case.lighting_double_bits);
        assert_bits_eq(
            &format!("moon {} shadow", case.name),
            shadow,
            expected_shadow,
        );
    }

    // 3. Earth + Moon (every case matches the patched-union Java oracle at 0 ULP,
    //    and every case where Orekit's mutual subtraction does not fire —
    //    including single-clear-body, total, disjoint-partial, and grazing
    //    overshoot disjoint cases — also matches raw Orekit at 0 ULP).
    let mut raw_orekit_checked = 0usize;
    for case in &fixture.earth_moon_cases {
        let sat = parse_vec3(&case.sat_km_bits);
        let sun = parse_vec3(&case.sun_km_bits);
        let moon = parse_vec3(&case.moon_km_bits);
        let model = earth_model(case.earth_flattening);

        let shadow = shadow_fraction_with_model_and_moon(sat, sun, moon, model)
            .unwrap_or_else(|e| panic!("earth+moon {}: {e:?}", case.name));
        let expected_shadow = 1.0 - parse_f64(&case.union_lighting_double_bits);
        assert_bits_eq(
            &format!("earth+moon {} union shadow", case.name),
            shadow,
            expected_shadow,
        );

        let (field_shadow, field_grad) =
            shadow_fraction_with_model_moon_and_gradient(sat, sun, moon, model)
                .unwrap_or_else(|e| panic!("earth+moon {} grad: {e:?}", case.name));
        assert_bits_eq(
            &format!("earth+moon {} union field shadow", case.name),
            field_shadow,
            1.0 - parse_f64(&case.union_lighting_field_val_bits),
        );
        for axis in 0..3 {
            assert_bits_eq(
                &format!("earth+moon {} union grad[{axis}]", case.name),
                field_grad[axis],
                -parse_f64(&case.union_lighting_field_grad_bits[axis]) * M_PER_KM,
            );
        }

        let srp = base_srp.with_earth_shadow_model(model);
        let accel = srp
            .acceleration_with_sun_moon(Vector3::from(sat), Vector3::from(sun), Vector3::from(moon))
            .unwrap_or_else(|e| panic!("earth+moon {} accel: {e:?}", case.name));
        for axis in 0..3 {
            assert_bits_eq(
                &format!("earth+moon {} union accel[{axis}]", case.name),
                accel[axis],
                parse_f64(&case.union_accel_double_bits[axis]) / M_PER_KM,
            );
        }

        if !case.orekit_subtracts_mutual {
            raw_orekit_checked += 1;
            assert_bits_eq(
                &format!("earth+moon {} raw orekit shadow", case.name),
                shadow,
                1.0 - parse_f64(&case.orekit_lighting_double_bits),
            );
            assert_bits_eq(
                &format!("earth+moon {} raw orekit field shadow", case.name),
                field_shadow,
                1.0 - parse_f64(&case.orekit_lighting_field_val_bits),
            );
            for axis in 0..3 {
                assert_bits_eq(
                    &format!("earth+moon {} raw orekit grad[{axis}]", case.name),
                    field_grad[axis],
                    -parse_f64(&case.orekit_lighting_field_grad_bits[axis]) * M_PER_KM,
                );
                assert_bits_eq(
                    &format!("earth+moon {} raw orekit accel[{axis}]", case.name),
                    accel[axis],
                    parse_f64(&case.orekit_accel_double_bits[axis]) / M_PER_KM,
                );
            }
        }
    }
    assert_eq!(raw_orekit_checked, 26);
}
